// 寻找是否有满足条件子序列
bool findSeq(string &a, string &b) {
    int aIndex = 0;
    int bIndex = 0;
    while (aIndex < a.size()) {
        if (a[aIndex] == b[bIndex]) {
            // 重置为特殊字符，防止重复使用
            a[aIndex] = '#';
            bIndex+=1;
        }
        if (bIndex == b.size()) {
            return true;
        }
​
        aIndex++;
    }
    return false;
}
​
int handle(string a, string b) {
    int res = 0;
    while (findSeq(a, b)) {
        res++;
    }
    return res;
}
