public class Main {
    // 寻找是否有满足条件的子序列
    private static boolean findSeq(StringBuilder a, String b) {
        int aIndex = 0, bIndex = 0;
        while (aIndex < a.length()) {
            if (a.charAt(aIndex) == b.charAt(bIndex)) {
                // 使用 '#' 作为标记，防止重复使用
                a.setCharAt(aIndex, '#');
                bIndex++;
            }
            if (bIndex == b.length()) {
                return true;
            }
            aIndex++;
        }
        return false;
    }
​
    private static int handle(String a, String b) {
        int res = 0;
        StringBuilder parent = new StringBuilder(a);
        while (findSeq(parent, b)) {
            res++;
        }
        return res;
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String parent = scanner.nextLine();
        String child = scanner.nextLine();
        scanner.close();

        if (parent.length() < child.length()) {
            System.out.println(0);
            return;
        }
        System.out.println(handle(parent, child));
    }
}
