def find_seq(a, b):

    a_index, b_index = 0, 0
    while a_index < len(a):
        if a[a_index] == b[b_index]:
            a[a_index] = '#'  
            b_index += 1
        if b_index == len(b):
            return True
        a_index += 1
    return False
​
def handle(a, b):
    res = 0
    # 转换为list方便修改
    a = list(a) 
    while find_seq(a, b):
        res += 1
    return res
