package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
// 寻找是否有满足条件的子序列
func findSeq(a *string, b string) bool {
    aRune := []rune(*a)
    aIndex, bIndex := 0, 0
    for aIndex < len(aRune) {
        if aRune[aIndex] == rune(b[bIndex]) {
            aRune[aIndex] = '#' 
            bIndex++
        }
        if bIndex == len(b) {
            *a = string(aRune)
            return true
        }
        aIndex++
    }
    return false
}
​
func handle(a, b string) int {
    res := 0
    for findSeq(&a, b) {
        res++
    }
    return res
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    parent, _ := reader.ReadString('\n')
    child, _ := reader.ReadString('\n')
​
    parent = strings.TrimSpace(parent)
    child = strings.TrimSpace(child)
​
    if len(parent) < len(child) {
        fmt.Println(0)
        return
    }
    fmt.Println(handle(parent, child))
}
